-- SAP S/4HANA -> canonical PO_LINE (SAP_A). Generated by tools/build_silver_sql.py.
SELECT 'SAP_A' AS SOURCE_SLOT, 'SAP S/4HANA' AS SOURCE_SYSTEM, h.BUKRS AS COMPANY_CODE, p.WERKS AS PLANT, p.EBELN AS PO_NUMBER, p.EBELP::STRING AS PO_ITEM, h.LIFNR AS SUPPLIER_ID,
  p.MATNR AS MATERIAL, p.TXZ01 AS ITEM_TEXT, p.MATKL AS MATERIAL_GROUP, p.MENGE AS QUANTITY, p.MEINS AS UOM,
  p.NETPR / NULLIF(p.PEINH, 0) AS NET_PRICE, p.NETWR AS NET_VALUE, h.WAERS AS CURRENCY, h.BEDAT AS PO_DATE, e.EINDT AS DELIVERY_DATE,
  p.KONNR AS CONTRACT_ID
FROM {{ source('src_s4_a', 'ekpo') }} p JOIN {{ source('src_s4_a', 'ekko') }} h ON h.EBELN = p.EBELN
LEFT JOIN {{ source('src_s4_a', 'eket') }} e ON e.EBELN = p.EBELN AND e.EBELP = p.EBELP AND e.ETENR = 1
WHERE COALESCE(p.LOEKZ, '') = '' AND h.BSTYP = 'F'
